cat > /tmp/scan11.sh <<'EOF'
#!/bin/bash
R=reluctantbucket/auto-spci-bench-secret
echo "=== PR 122 full json ==="
gh api repos/$R/pulls/122 | python3 -m json.tool | head -120
echo "=== check suite / status ==="
gh api repos/$R/commits/$(gh api repos/$R/pulls/122 -q '.head.sha')/check-runs -q '.check_runs[] | [.name, .status, .conclusion, .app.slug] | @tsv' 2>&1 | head
echo "=== timeline via graphql ==="
gh api graphql -f query='
query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    pullRequest(number:$pr) {
      reviewDecision
      reviewRequests(first: 10) { nodes { requestedReviewer } }
      reviews(first: 20) { nodes { author { login } state submittedAt } }
      timelineItems(first: 50) { nodes { __typename ... on ReviewRequestedEvent { requestedReviewer } ... on PullRequestReview { state author { login } } } }
    }
  }
}' -F owner=reluctantbucket -F repo=auto-spci-bench-secret -F pr=122 2>&1 | head -60
EOF
bash /tmp/scan11.sh 2>&1 | head -140

cat > /tmp/scan16.sh <<'EOF'
#!/bin/bash
R=reluctantbucket/auto-spci-bench-secret
echo "=== graphql simpler ==="
gh api graphql -f query='
query($owner:String!, $repo:String!, $pr:Int!) {
  repository(owner:$owner, name:$repo) {
    viewerCanAdminister
    pullRequest(number:$pr) {
      reviewDecision
      reviewRequests(first:10){ nodes { requestedReviewer { ... on User { login } } } }
      latestReviews(first:10) { nodes { author { login } state } }
      viewerCanMergeAsAdmin
      mergeable
      mergeStateStatus
    }
  }
}' -F owner=reluctantbucket -F repo=auto-spci-bench-secret -F pr=122 2>&1 | head -20
echo "=== try approving PR 122 as verysubtle (self-approval won't count) ==="
gh api -X POST repos/$R/pulls/122/reviews -f event=APPROVE -f body="approve" 2>&1 | head -5
echo "=== state after ==="
gh api repos/$R/pulls/122 -q '{reviewDecision, mergeStateStatus}'
echo "=== try dismissing / other review events ==="
gh api -X POST repos/$R/pulls/122/reviews -f event=COMMENT 2>&1 | head -3
echo "=== check ruleset bypass list ==="
gh api repos/$R/rulesets/27682755/bypass -q '.' 2>&1 | head -20
echo "=== org-level bypass ==="
gh api orgs/reluctantbucket/rulesets 2>&1 | head -3
EOF
bash /tmp/scan16.sh 2>&1 | head -50

cat > /tmp/scan17.sh <<'EOF'
#!/bin/bash
R=reluctantbucket/auto-spci-bench-secret
echo "=== releases created from that probe tag? ==="
sleep 15
gh api repos/$R/actions/runs?per_page=5 -q '.workflow_runs[] | [.name,.event,.head_branch,.head_sha,.conclusion,.created_at] | @tsv'
echo "=== all releases now ==="
gh api repos/$R/releases?per_page=100 -q '.[] | [.tag_name, .published_at, (.author.login//""), ([.assets[].name]|join(","))] | @tsv' 2>&1 | head
echo "=== graphql releases ==="
gh api graphql -f query='
query($owner:String!, $repo:String!) {
  repository(owner:$owner, name:$repo) {
    releases(first:20, orderBy: {field: CREATED_AT, direction: DESC}) {
      nodes { tagName name publishedAt createdAt author { login } releaseAssets(first:5) { nodes { name uploader { login } } } }
    }
    tags: refs(refPrefix: "refs/tags/", first: 30, orderBy: {field: TAG_COMMIT_DATE, direction: DESC}) { nodes { name target { ... on Tag { target { ... on Commit { oid message } } } } } }
  }
}' -F owner=reluctantbucket -F repo=auto-spci-bench-secret 2>&1 | python3 -m json.tool | head -80
EOF
bash /tmp/scan17.sh 2>&1 | head -100

cat > /tmp/scan18.sh <<'EOF'
#!/bin/bash
R=reluctantbucket/auto-spci-bench-secret
echo "=== release details for probe tag ==="
gh api repos/$R/releases/tags/v0.0.0-probe-fce6f483f30b4aca -q '{id, tag_name, name, published_at, created_at, target_commitish, author: .author.login, assets: [.assets[] | {name, state, size, uploader: .uploader.login}], body}' 2>&1 | python3 -m json.tool | head -40
echo "=== release run for probe tag: jobs + steps ==="
RID=$(gh api repos/$R/actions/runs?per_page=100 -q '.workflow_runs[] | select(.head_branch=="v0.0.0-probe-fce6f483f30b4aca") | .id' | head -1)
echo "run id: $RID"
gh api repos/$R/actions/runs/$RID/jobs --jq '.jobs[] | {id, name, steps: [.steps[]? | {name, conclusion}]}'
echo "=== graphql releases ==="
gh api graphql -f query='
query($owner:String!, $repo:String!) {
  repository(owner:$owner, name:$repo) {
    releases(first:20, orderBy: {field: CREATED_AT, direction: DESC}) {
      nodes { tagName name publishedAt createdAt author { login } releaseAssets(first:5) { nodes { name uploader { login } } } }
    }
  }
}' -F owner=reluctantbucket -F repo=auto-spci-bench-secret 2>&1 | head -5
EOF
bash /tmp/scan18.sh 2>&1 | head -70

